(
  $wo := [workOrder.edges.node.(
    $id := id;
    $merge([$,{"order":$state.context.REQUEST.DATA.workOrder[id=$id].order}])
    )];
  $owo := $wo^(order);
  {
    "LOCAL":{
      "time": $moment(),
      "timeZone":setting.edges.node.defaultValue,
      "workOrder": [$owo],
      "request": (
        $p := [$owo].(
          $wo := $;          
          workOrderProcesses.edges^($parseInt(node.order))#$i.node.(
            $durationMs := $coalesce([workOrderProcessDistributions.edges[0].node.distributionGroup.estimatedTime,0])+($coalesce([workOrderProcessDistributions.edges[0].node.distributionGroup.setupRate,0])*3600000);

            {
              "id": workOrderProcessDistributions.edges[0].node.distributionGroup.id,
              "dependsOnIds": $i = 0  ? [] : [$wo.workOrderProcesses.edges[$i-1].node.workOrderProcessDistributions.edges[0].node.distributionGroup.id],
              "availabilityCalendarIds": [workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.shiftGroup.calendarId],
              "targetCalendarId": workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.calendarId,
              "totalDurationMs": $durationMs,
              "durationMs": $durationMs,
              "metaData":$.{
                "workOrderId":$wo.id,
                "initial": $i = 0,
                "final":$count($wo.workOrderProcesses.edges.node)=$i+1,
                "distributionId": workOrderProcessDistributions.edges[0].node.id,
                "distributionGroupId":workOrderProcessDistributions.edges[0].node.distributionGroup.id,
                "workOrderProcessId": id,
                "workcenterId":workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.id,
                "workcenterName": workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.name,
                "calendarId":workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.calendarId,
                "code": code
              },

              /* $merge([$,{"workOrderId":$wo.id,"final":$count($wo.workOrderProcesses.edges.node)=$i+1}]), */

              "constraints": {
                "earliestStart":$coalesce([workOrderProcessDistributions.edges[0].node.distributionGroup.earliestStartAt[$!=null],$now()]),
                "mustEndBy": $wo.promiseAt[$!=null],
                "mustStartBy": workOrderProcessDistributions.edges[0].node.distributionGroup.latestStartAt[$!=null],
                "infiniteCapacity": workOrderProcessDistributions.edges[0].node.distributionGroup.workcenter.constraint != true
              }
            } 
          )
        );

        $g := $groupBy([$p], function ($v) { $v.id });

        {
          "options": {"debug":true},
          "schedulingGroups": [
            $each($g, function($v, $k) {(
              $count($v) = 1 
              ? $v[0] 
              : {
                "id": $v[0].id,
                "dependsOnIds": [$v.dependsOnIds],
                "availabilityCalendarIds": $v[0].availabilityCalendarIds,
                "targetCalendarId": $v[0].targetCalendarId,
                "totalDurationMs": $v[0].durationMs,
                "durationMs": $v[0].durationMs,
                "metaData": $v.metaData,
                "constraints": {
                  "earliestStart": $not($isNilOrEmpty($v.[constraints.earliestStart]))  ? $sort($v.constraints.earliestStart, function($l, $r) {
                    $l > $r
                  })[0],
                  "mustEndBy":$not($isNilOrEmpty($v.[constraints.mustEndBy]))  ? $sort($v.constraints.mustEndBy, function($l, $r) {
                    $l > $r
                  })[0],
                  "mustStartBy": $not($isNilOrEmpty($v.[constraints.mustStartBy]))  ? $sort($v.constraints.mustStartBy, function($l, $r) {
                    $l > $r
                  })[0],
                  "infiniteCapactity": $not($isNilOrEmpty($v.[constraints.infiniteCapacity]))  ? $v[0].constraints.infiniteCapacity
                }
              }
            )})
          ]
        } 
      )   
    }
  } 
)

data.query:
query D($whereW: WorkOrderWhereInput, $orderBy: [WorkOrderOrderByInput!]!) {
  workOrder(where: $whereW, orderBy: $orderBy) {
    edges {
      node {
        id
        earliestStartAt
        productStrategy {
          product {
            id
            name
          }
          code
        }
        workOrderProcesses(where: {workOrderProcessStatusId: {_in: ["New", "Started"]}}, orderBy: {field: order, direction: asc}) {
          edges {
            node {
              id
              code
              order
              quantity
              productStrategyProcessId
              workOrderProcessDistributions(where: {workOrderProcessDistributionStatusId: {_in: ["New", "Started"]}}) {
                edges {
                  node {
                    distributionGroup {
                      id
                      workOrderProcessDistributionStatusId
                      setupRate
                      estimatedTime
                      earliestStartAt
                      calendarEventId
                      workcenter {
                        id
                        name
                        calendarId
                        shiftGroup {
                          id
                          calendarId
                        }
                        constraint
                      }
                      distributions {
                        edges {
                          node {
                            id
                            workOrderProcess {
                              id
                              order
                              workOrder {
                                id
                                number
                              }
                              workOrderProcessBoms {
                                edges {
                                  node {
                                    bomAssignments {
                                      edges {
                                        node {
                                          workOrder {
                                            workOrderDistributions {
                                              edges {
                                                node {
                                                  id
                                                  distributionGroupId
                                                }
                                              }
                                            }
                                          }
                                        }
                                      }
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                        total
                      }
                    }
                    id
                    calendarEventId
                    workOrder {
                      id
                      number
                    }
                  }
                }
              }
            }
          }
          total
        }
      }
    }
  }
  setting(where: {id: {_eq: "TimeZone"}}) {
    edges {
      node {
        defaultValue
      }
    }
  }
}

